package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="ledger_transactions") public class LedgerTransaction{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(optional=false) private TransferTransaction transfer;@OneToOne(optional=false) @JoinColumn(name="leg_id",unique=true) private TransferLeg leg;@Column(name="transaction_type",nullable=false,length=40) private String transactionType;@Column(nullable=false,length=20) private String status;@Column(name="posted_at",nullable=false) private Instant postedAt;@OneToMany(mappedBy="ledgerTransaction",cascade=CascadeType.ALL) private List<LedgerEntry> entries=new ArrayList<>();public UUID getId(){return id;}public void setTransfer(TransferTransaction v){transfer=v;}public void setLeg(TransferLeg v){leg=v;}public void setTransactionType(String v){transactionType=v;}public void setStatus(String v){status=v;}public void setPostedAt(Instant v){postedAt=v;}public List<LedgerEntry> getEntries(){return entries;}}
